const modalSet = new Set(["can", "could", "may", "might", "must", "shall", "should", "will", "would"]);

function getVerbCategory(present) {
  const normalized = present.toLowerCase();
  const categories = [];
  categories.push(irregularSet.has(normalized) ? "Irregular Verb" : "Regular Verb");
  categories.push(stativeSet.has(normalized) ? "State Verb" : "Action Verb");
  categories.push(transitiveSet.has(normalized) ? "Transitive Verb" : "Intransitive Verb");
  if (modalSet.has(normalized)) categories.push("Modal Verb");
  if (normalized === "be" || normalized === "have" || normalized === "do") {
    categories.push("Auxiliary Verb");
  }
  return [...new Set(categories)].join(", ");
}

